from collections import Counter
from solution import anti_shuffle

import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st


# --- explicit spec examples ---

def test_example_Hi():
    assert anti_shuffle('Hi') == 'Hi'


def test_example_hello():
    assert anti_shuffle('hello') == 'ehllo'


def test_example_Hello_World():
    assert anti_shuffle('Hello World!!!') == 'Hello !!!Wdlor'


def test_example_empty_string():
    # empty string has no words; ordered version is itself
    assert anti_shuffle('') == ''


def test_example_single_space_preserved():
    assert anti_shuffle(' ') == ' '


def test_example_only_spaces_preserved():
    assert anti_shuffle('   ') == '   '


def test_example_leading_trailing_spaces():
    # order of words and blank spaces kept: leading/trailing spaces stay
    assert anti_shuffle(' hello ') == ' ehllo '


def test_example_multiple_blank_spaces():
    assert anti_shuffle('a  b') == 'a  b'
    assert anti_shuffle('ba  dc') == 'ab  cd'


# --- reference model (written independently from spec) ---

def reference_anti_shuffle(s):
    # Keep every ' ' exactly where it is; sort each maximal
    # run of non-space characters by ord ascending.
    out = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            out.append(' ')
            i += 1
        else:
            j = i
            while j < n and s[j] != ' ':
                j += 1
            word = s[i:j]
            out.append(''.join(sorted(word, key=ord)))
            i = j
    return ''.join(out)


ascii_with_space = st.text(
    alphabet=st.characters(min_codepoint=32, max_codepoint=126),
    max_size=30,
)
general_text = st.text(
    alphabet=st.characters(min_codepoint=1, max_codepoint=1000),
    max_size=20,
)
space_heavy = st.text(
    alphabet=st.sampled_from([' ', ' ', 'a', 'b', 'H', 'e', 'l', 'o', '!', 'Z', '0']),
    max_size=30,
)


@given(s=ascii_with_space)
def test_property_length_preserved(s):
    assert len(anti_shuffle(s)) == len(s)


@given(s=space_heavy)
def test_property_space_positions_preserved(s):
    r = anti_shuffle(s)
    assert len(r) == len(s)
    for a, b in zip(s, r):
        assert (a == ' ') == (b == ' ')
    # spaces themselves unchanged
    assert [c for c in r if c == ' '] == [c for c in s if c == ' ']


@given(s=ascii_with_space)
def test_property_each_word_sorted_by_ascii(s):
    r = anti_shuffle(s)
    # split preserving empties on single space
    r_words = r.split(' ')
    for w in r_words:
        assert list(w) == sorted(w, key=ord)
        # ascii values non-decreasing
        assert all(ord(w[k]) <= ord(w[k + 1]) for k in range(len(w) - 1))


@given(s=ascii_with_space)
def test_property_each_word_is_permutation(s):
    r = anti_shuffle(s)
    s_words = s.split(' ')
    r_words = r.split(' ')
    assert len(s_words) == len(r_words)
    for sw, rw in zip(s_words, r_words):
        assert Counter(sw) == Counter(rw)


@given(s=general_text)
def test_property_reference_model_equivalence(s):
    # strip nothing; reference handles any str; only ' ' is separator
    # avoid '\x00'-like surprises: still valid str, reference works
    assert anti_shuffle(s) == reference_anti_shuffle(s)


@given(s=space_heavy)
def test_property_idempotence(s):
    once = anti_shuffle(s)
    assert anti_shuffle(once) == once


@given(s=ascii_with_space)
def test_property_single_word_without_space_is_sorted(s):
    word = s.replace(' ', '')
    # word itself contains no space, so it is a single word
    assert anti_shuffle(word) == ''.join(sorted(word, key=ord))


@given(s=ascii_with_space)
def test_property_words_order_and_count_preserved(s):
    # number of space-separated tokens preserved (including empties from
    # consecutive/leading/trailing spaces)
    r = anti_shuffle(s)
    assert len(r.split(' ')) == len(s.split(' '))
